//! 🧪️ Same paged source and real token recipient deliver the native identity under the authored17-byte grant.
use super::*;
use crate::ToolRunReceivingLimits;
use protocol::codec::{RetainedWireByteSource,OriginalWireSourceIdentity};
struct Pages<'a>{bytes:&'a[u8],identity:OriginalWireSourceIdentity}
impl RetainedWireByteSource for Pages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{self.identity}fn byte_at(&self,index:usize)->Option<u8>{self.bytes.chunks(7).nth(index/7)?.get(index%7).copied()}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn hex(text:&str)->Vec<u8>{text.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
#[test]
fn original_typed_identity_receiving_preserves_paid_tokens_and_every_native_interruption(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let bytes=hex(law["bodyHex"].as_str().unwrap());let source=Pages{identity:OriginalWireSourceIdentity{address:bytes.as_ptr()as usize,extent:bytes.len(),authority:Some((42,7))},bytes:&bytes};
 let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:17,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let metadata=RetainedCloneGrant{maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,..g};
 let tick_corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../🧪️tests/🧫️fixtures/🎞️ticks.json")).unwrap();let reference=crate::ToolRunTick::decode(&hex(tick_corpus["ticks"][1]["hex"].as_str().unwrap())).unwrap().identity;
 for stop in law["interruptAfter"].as_array().unwrap(){let stop=stop.as_u64().unwrap()as usize;let((mut lower,_),mut physical)=observe(||{let mut lower=RetainedRecordBodySourceDecode::admit(&source,(0,bytes.len()),ToolRunReceivingLimits::REPORTS.tick.record_body(),g).unwrap().unwrap();let receipt=lower.take_receipt().unwrap();assert_eq!(receipt.0,g);assert!(receipt.1.fits(g));(lower,receipt)});
  for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:1,..g}]{let(result,heap)=observe(||ToolRunIdentityReceiving::admit(&lower,denied));assert!(result.is_none());assert_eq!(heap,(0,0))}
  let((mut typed,progress),heap)=observe(||ToolRunIdentityReceiving::admit(&lower,g).unwrap());assert_eq!(heap,(0,0));assert_eq!(typed.take_receipt().unwrap(),(g,progress));
  let(mut other,heap)=observe(||RetainedRecordBodySourceDecode::admit(&source,(1,bytes.len()),ToolRunReceivingLimits::REPORTS.tick.record_body(),g).unwrap().unwrap());assert_eq!(heap,(0,0));other.take_receipt().unwrap();assert_eq!(other.source_identity(),lower.source_identity());assert_ne!(other.original_range(),lower.original_range());let mut offered=Some(RetainedRecordBodyToken::Value(RetainedValueToken::Begin{kind:RetainedValueContainer::Record,count:4}));let before=offered;let(denied,heap)=observe(||typed.receive(&other,&mut offered,g));assert!(denied.is_err());assert_eq!(heap,(0,0));assert_eq!(offered,before);assert!(typed.receipt().is_none());drop(denied);other.cancel();while !other.terminal_is_empty(){let(_,heap)=observe(||other.close_step(g).unwrap());let(issued,p)=other.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);physical.0+=heap.0;physical.1+=heap.1;}let(_,heap)=observe(||drop(other));assert_eq!(heap,(0,0));
  let(mut pending,mut accepted,mut copied)=(None,0,0);
  for _ in 0..10000{if accepted>=stop||typed.identity().is_some(){break}if lower.token().is_some(){let(result,heap)=observe(||lower.take_token_into(&mut pending,g).unwrap());assert!(result);assert_eq!(heap,(0,0));assert_eq!(lower.take_receipt().unwrap().0,g)}
   if pending.is_some(){if !matches!(pending,Some(RetainedRecordBodyToken::Value(_))){assert!(matches!(pending,Some(RetainedRecordBodyToken::Catalog{symbols:0}|RetainedRecordBodyToken::CatalogComplete)));pending=None;continue}
    let before=pending;for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),Some(RetainedCloneGrant{maximum_depth:1,..g}),if typed.demands().copy_bytes>0{Some(metadata)}else{None}].into_iter().flatten(){let(result,heap)=observe(||typed.receive(&lower,&mut pending,denied).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(pending,before);assert!(typed.receipt().is_none())}
    let(result,heap)=observe(||typed.receive(&lower,&mut pending,g).unwrap());let progress=result.unwrap();assert_eq!(heap,(0,0));assert!(progress.fits(g));assert!(pending.is_none());let mut blocked=before;assert!(typed.receive(&lower,&mut blocked,g).unwrap().is_none());assert_eq!(blocked,before);assert_eq!(typed.take_receipt().unwrap(),(g,progress));copied+=progress.copied_bytes;accepted+=1;continue
   }
   let(status,heap)=observe(||lower.step(&source,g).unwrap());assert_ne!(status,pack::record::RetainedRecordBodySourceStep::Fault);let(issued,progress)=lower.take_receipt().unwrap();assert_eq!(issued,g);assert!(progress.fits(g));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap);physical.0+=heap.0;physical.1+=heap.1;
  }
  if stop==1000{assert_eq!(copied,32);assert_eq!(typed.identity(),Some(&reference));let mut recipient=None;assert!(typed.take_identity_into(&mut recipient,RetainedCloneGrant{maximum_items:0,..metadata}).is_none());let(progress,heap)=observe(||typed.take_identity_into(&mut recipient,metadata).unwrap());assert_eq!(heap,(0,0));assert_eq!(recipient,Some(reference));assert_eq!(typed.take_receipt().unwrap(),(metadata,progress));assert_eq!(progress.copied_bytes,0);let mut repeated=Some(RetainedRecordBodyToken::Value(RetainedValueToken::End(RetainedValueContainer::Record)));let before=repeated;let(blocked,heap)=observe(||typed.receive(&lower,&mut repeated,g).unwrap());assert!(blocked.is_none());assert_eq!(repeated,before);assert_eq!(heap,(0,0));}
  typed.cancel();let(progress,heap)=observe(||typed.close_step(metadata).unwrap());assert_eq!(heap,(0,0));assert_eq!(typed.take_receipt().unwrap(),(metadata,progress));assert!(typed.terminal_is_empty());lower.cancel();
  while !lower.terminal_is_empty(){if lower.token().is_some(){assert!(lower.take_token_into(&mut pending,g).unwrap());lower.take_receipt().unwrap();pending=None;}let(_,heap)=observe(||lower.close_step(g).unwrap());let(issued,progress)=lower.take_receipt().unwrap();assert_eq!(issued,g);assert!(progress.fits(g));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap);physical.0+=heap.0;physical.1+=heap.1;}
  assert_eq!(physical.0,physical.1);let((),heap)=observe(||{drop(typed);drop(lower)});assert_eq!(heap,(0,0));println!("[DEBUG] original identity cut={stop} typedTokens={accepted} revisionCopy={copied} exactNativeBirthRelease={} fixed17 metadata0 terminalDrop0",physical.0);
 }
}
